import base64
import io

import streamlit as st
from PIL import Image

# ============================================================
# CALCULADORA DE PALÉS — Streamlit
# ============================================================

# Copia de seguridad del logo dentro del propio código.
# Así la aplicación sigue funcionando aunque el entorno
# temporal no encuentre logo.png en la ruta esperada.
LOGO_B64 = ""
LOGO_BYTES = base64.b64decode(LOGO_B64)

st.set_page_config(
    page_title="Calculadora de Palés",
    page_icon=Image.open(io.BytesIO(LOGO_BYTES)),
    layout="centered",
    initial_sidebar_state="collapsed",
)

if "dark_mode" not in st.session_state:
    st.session_state.dark_mode = False

theme = "dark" if st.session_state.dark_mode else "light"

st.markdown(
    f"""
    <style>
    :root {{
        --bg: {"#101820" if theme == "dark" else "#f4f6f8"};
        --card: {"#18232d" if theme == "dark" else "#ffffff"};
        --text: {"#F5F7FA" if theme == "dark" else "#17202a"};
        --muted: {"#AAB7C4" if theme == "dark" else "#475467"};
        --border: {"#334454" if theme == "dark" else "#d9e0e7"};
        --primary: #174a7e;
        --primary-dark: #123a63;
        --soft: {"#22384B" if theme == "dark" else "#edf4fa"};
        --danger: #ef6b61;
        --question-color: {"#F8FAFC" if theme == "dark" else "#111827"};
        --description-color: {"#B9C7D5" if theme == "dark" else "#344054"};
        --button-text: {"#FFFFFF" if theme == "dark" else "#111827"};
    }}

    .stApp {{ background:var(--bg); }}

    .block-container {{
        width:min(900px,100%);
        padding-top:1rem;
        padding-bottom:1.5rem;
    }}

    [data-testid="stHeader"] {{ background:transparent; }}

    /* Botón de modo oscuro */
    .theme-button {{
        position: absolute;
        right: 0;
        top: 0;
    }}

    .theme-button div.stButton > button {{
        min-height: 42px !important;
        width: 42px !important;
        padding: 0 !important;
        border-radius: 50% !important;
        border: 1px solid var(--border) !important;
        background: var(--card) !important;
        color: var(--text) !important;
        font-size: 18px !important;
        box-shadow: none !important;
    }}

    .header {{
        position:relative;
        min-height:122px;
        display:flex;
        align-items:center;
        justify-content:center;
        padding:12px 100px 12px 20px;
    }}

    .brand {{ text-align:center; }}
    .brand h1 {{
        margin:0;
        color:var(--text);
        font-size:clamp(21px,4vw,30px);
        line-height:1.15;
        letter-spacing:.02em;
    }}
    .brand p {{
        margin:8px 0 0;
        color:var(--muted);
        font-weight:500;
        font-size:clamp(13px,2.4vw,15px);
    }}

    .logo {{
        position:absolute;
        right:50px;
        top:50%;
        width:78px;
        height:78px;
        object-fit:contain;
        transform:translateY(-50%);
    }}

    .progress-label {{
        margin:4px 0 8px;
        color:var(--muted);
        font-size:12px;
        font-weight:800;
        letter-spacing:.08em;
    }}

    .progress {{
        display:grid;
        grid-template-columns:repeat(5,1fr);
        gap:5px;
        margin-bottom:15px;
    }}

    .progress div {{
        height:5px;
        border-radius:999px;
        background:var(--border);
    }}

    .progress div.active {{ background:var(--primary); }}

    .question-card,
    .result-card {{
        background:var(--card);
        border:1px solid var(--border);
        border-radius:18px;
        box-shadow:0 8px 24px rgba(0,0,0,{"0.18" if theme == "dark" else "0.05"});
        padding:clamp(25px,5vw,45px);
        margin-bottom:12px;
    }}

    .question {{
        margin:0;
        color:var(--text);
        font-size:clamp(23px,5.2vw,34px);
        line-height:1.18;
        font-weight:700;
    }}

    .description {{
        max-width:700px;
        margin:13px 0 28px;
        color:var(--muted);
        font-weight:500;
        font-size:clamp(14px,2.6vw,17px);
        line-height:1.55;
    }}

    div[data-testid="stNumberInput"] label {{ display:none; }}

    div[data-testid="stNumberInput"] input {{
        min-height:64px;
        border:2px solid var(--border);
        border-radius:12px;
        background:var(--card);
        color:var(--text);
        text-align:center;
        font-size:clamp(22px,5vw,30px);
    }}

    .unit {{
        min-height:64px;
        display:flex;
        align-items:center;
        justify-content:center;
        border-radius:12px;
        background:var(--soft);
        color:{"#8DBCE5" if theme == "dark" else "#174a7e"};
        font-size:16px;
        font-weight:800;
        padding:0 14px;
    }}

    .error {{
        min-height:23px;
        color:var(--danger);
        font-size:14px;
        margin:5px 0 4px;
    }}

    div.stButton > button {{
        color:var(--text);
        min-height:54px;
        border-radius:12px;
        font-weight:800;
        border:1px solid var(--border);
    }}

    .next-button div.stButton > button {{
        border-color:var(--primary);
        background:var(--primary);
        color:#fff;
    }}

    .back-button div.stButton > button {{
        background:var(--card);
        color:var(--text) !important;
    }}

    .result-card {{ text-align:center; }}

    .eyebrow {{
        color:var(--muted);
        font-size:12px;
        font-weight:800;
        letter-spacing:.08em;
    }}

    .result-title {{
        margin:10px 0 0;
        color:var(--text);
        font-size:clamp(25px,6vw,38px);
        line-height:1.15;
        font-weight:700;
    }}

    .net {{
        margin:22px 0 25px;
        padding:22px 14px;
        border-radius:16px;
        background:var(--soft);
        color:{"#8DBCE5" if theme == "dark" else "#174a7e"};
        font-size:clamp(39px,10vw,66px);
        font-weight:900;
        line-height:1.05;
        overflow-wrap:anywhere;
    }}

    .result-note {{
        margin:0 auto;
        max-width:620px;
        color:var(--muted);
        font-weight:500;
        font-size:14px;
        line-height:1.55;
    }}

    .footer {{
        margin-top:12px;
        color:var(--muted);
        font-weight:500;
        text-align:center;
        font-size:12px;
    }}

    @media (max-width:560px) {{
        .block-container {{
            padding-left:.75rem;
            padding-right:.75rem;
        }}

        .header {{
            min-height:96px;
            padding-right:72px;
        }}

        .logo {{
            width:56px;
            height:56px;
            right:44px;
        }}

        .theme-button {{
            top:2px;
        }}

        .question-card,
        .result-card {{
            border-radius:15px;
            padding:25px 18px;
        }}

        .unit {{ margin-top:5px; }}
    }}

    /* Contraste robusto en modo claro y oscuro */
    .question {{
        color: var(--question-color) !important;
        -webkit-text-fill-color: var(--question-color) !important;
    }}

    .description {{
        color: var(--description-color) !important;
        -webkit-text-fill-color: var(--description-color) !important;
    }}

    .next-button div.stButton > button,
    .next-button div.stButton > button *,
    .next-button div.stButton > button p,
    .next-button div.stButton > button span {{
        color: #FFFFFF !important;
        -webkit-text-fill-color: #FFFFFF !important;
    }}

    .back-button div.stButton > button,
    .back-button div.stButton > button *,
    .back-button div.stButton > button p,
    .back-button div.stButton > button span {{
        color: var(--button-text) !important;
        -webkit-text-fill-color: var(--button-text) !important;
    }}

    /* Botones: colores explícitos y legibles en ambos modos.
       Se aplican al botón real renderizado por Streamlit. */
    div[data-testid="stButton"] > button[data-testid="stBaseButton-secondary"] {{
        background-color: #FFFFFF !important;
        border: 1px solid #344054 !important;
        color: #111827 !important;
        -webkit-text-fill-color: #111827 !important;
        opacity: 1 !important;
    }}

    div[data-testid="stButton"] > button[data-testid="stBaseButton-secondary"]:hover {{
        background-color: #F2F4F7 !important;
        border-color: #174A7E !important;
        color: #111827 !important;
        -webkit-text-fill-color: #111827 !important;
    }}

    div[data-testid="stButton"] > button[data-testid="stBaseButton-primary"] {{
        background-color: #174A7E !important;
        border: 1px solid #174A7E !important;
        color: #FFFFFF !important;
        -webkit-text-fill-color: #FFFFFF !important;
        opacity: 1 !important;
    }}

    div[data-testid="stButton"] > button[data-testid="stBaseButton-primary"]:hover {{
        background-color: #123A63 !important;
        border-color: #123A63 !important;
        color: #FFFFFF !important;
        -webkit-text-fill-color: #FFFFFF !important;
    }}

    div[data-testid="stButton"] > button[data-testid="stBaseButton-primary"] *,
    div[data-testid="stButton"] > button[data-testid="stBaseButton-primary"] p,
    div[data-testid="stButton"] > button[data-testid="stBaseButton-primary"] span {{
        color: #FFFFFF !important;
        -webkit-text-fill-color: #FFFFFF !important;
    }}

    div[data-testid="stButton"] > button[data-testid="stBaseButton-secondary"] *,
    div[data-testid="stButton"] > button[data-testid="stBaseButton-secondary"] p,
    div[data-testid="stButton"] > button[data-testid="stBaseButton-secondary"] span {{
        color: #111827 !important;
        -webkit-text-fill-color: #111827 !important;
    }}

    /* El botón de tema mantiene su diseño compacto */
    .theme-button + div[data-testid="stButton"] > button {{
        min-height: 42px !important;
    }}

    /* 0,00 / 0 como placeholder: no debe parecer un dato introducido */
    div[data-testid="stNumberInput"] input::placeholder {
        color: transparent !important;
        -webkit-text-fill-color: transparent !important;
        opacity: 0 !important;
    }

    div[data-testid="stNumberInput"] input::-webkit-input-placeholder {
        color: transparent !important;
        -webkit-text-fill-color: transparent !important;
        opacity: 0 !important;
    }
    </style>
    """,
    unsafe_allow_html=True,
)


theme_col = st.container()
with theme_col:
    st.markdown('<div class="theme-button">', unsafe_allow_html=True)
    icon = "☀️" if st.session_state.dark_mode else "🌙"
    label = "Cambiar a modo claro" if st.session_state.dark_mode else "Cambiar a modo oscuro"
    if st.button(icon, help=label, key="theme_toggle"):
        st.session_state.dark_mode = not st.session_state.dark_mode
        st.rerun()
    st.markdown('</div>', unsafe_allow_html=True)

st.markdown(
    """
    <header class="header">
        <div class="brand">
            <h1>CALCULADORA DE PALÉS</h1>
            <p>Calcula el peso neto de forma rápida y sencilla</p>
        </div>
        <img class="logo" src="data:image/png;base64," alt="Logotipo">
    </header>
    """.replace("", LOGO_B64),
    unsafe_allow_html=True,
)

steps = [
    {
        "key": "total",
        "title": "¿Cuál es el peso total del palé?",
        "description": "Introduce el peso del palé completo, con todos los productos y embalajes.",
        "unit": "kg",
        "step": 0.01,
    },
    {
        "key": "pallet",
        "title": "¿Cuál es el peso del palé vacío?",
        "description": "Introduce únicamente el peso del palé, sin ningún producto encima.",
        "unit": "kg",
        "step": 0.01,
    },
    {
        "key": "wrapping",
        "title": "¿Cuánto pesa el fardo o envoltorio?",
        "description": "Introduce el peso del envoltorio que agrupa las cajas, sin contar las cajas.",
        "unit": "kg",
        "step": 0.01,
    },
    {
        "key": "box",
        "title": "¿Cuánto pesa una caja vacía?",
        "description": "Introduce el peso de una sola caja, sin ningún producto dentro.",
        "unit": "kg",
        "step": 0.01,
    },
    {
        "key": "boxes",
        "title": "¿Cuántas cajas lleva el fardo?",
        "description": "Introduce el número de cajas que hay dentro del fardo.",
        "unit": "cajas",
        "step": 1,
    },
]

if "current_step" not in st.session_state:
    st.session_state.current_step = 0
if "inputs" not in st.session_state:
    st.session_state.inputs = {}
if "result" not in st.session_state:
    st.session_state.result = None
if "error" not in st.session_state:
    st.session_state.error = ""


def reset():
    st.session_state.current_step = 0
    st.session_state.inputs = {}
    st.session_state.result = None
    st.session_state.error = ""


def calculate_next():
    step = steps[st.session_state.current_step]
    value = st.session_state.get(f"input_{step['key']}")

    if value is None or value < 0:
        st.session_state.error = "Introduce un valor válido mayor o igual que 0."
        return

    if step["key"] == "boxes" and int(value) != value:
        st.session_state.error = "El número de cajas debe ser un número entero."
        return

    st.session_state.inputs[step["key"]] = value
    st.session_state.error = ""

    if st.session_state.current_step < len(steps) - 1:
        st.session_state.current_step += 1
        return

    v = st.session_state.inputs
    net = v["total"] - v["pallet"] - v["wrapping"] - (v["box"] * v["boxes"])

    if net < 0:
        st.session_state.error = (
            "El peso neto es negativo. Revisa los datos introducidos."
        )
        return

    st.session_state.result = round(net, 2)


if st.session_state.result is not None:
    result_text = (
        f"{st.session_state.result:,.2f} kg"
        .replace(",", "X")
        .replace(".", ",")
        .replace("X", ".")
    )

    st.markdown(
        f"""
        <section class="result-card">
            <div class="eyebrow">RESULTADO</div>
            <div class="result-title">Peso neto del producto</div>
            <div class="net">{result_text}</div>
            <p class="result-note">
                Resultado después de descontar el palé, el fardo o envoltorio
                y el peso de las cajas vacías.
            </p>
        </section>
        """,
        unsafe_allow_html=True,
    )

    if st.button("NUEVO CÁLCULO", use_container_width=True):
        reset()
        st.rerun()

else:
    current = st.session_state.current_step
    step = steps[current]

    active_bars = "".join(
        f'<div class="{"active" if i <= current else ""}"></div>'
        for i in range(len(steps))
    )

    st.markdown(
        f"""
        <div class="progress-label">PASO {current + 1} DE {len(steps)}</div>
        <div class="progress">{active_bars}</div>
        <section class="question-card">
            <h2 class="question">{step["title"]}</h2>
            <p class="description">{step["description"]}</p>
        """,
        unsafe_allow_html=True,
    )

    col_input, col_unit = st.columns([5, 1], gap="small")

    with col_input:
        existing = st.session_state.inputs.get(step["key"])
        st.number_input(
            "Dato",
            min_value=0.0,
            value=float(existing) if existing is not None else 0.0,
            step=float(step["step"]),
            format="%.2f" if step["key"] != "boxes" else "%.0f",
            key=f"input_{step['key']}",
            label_visibility="collapsed",
        )

    with col_unit:
        st.markdown(
            f'<div class="unit">{step["unit"]}</div>',
            unsafe_allow_html=True,
        )

    if st.session_state.error:
        st.markdown(
            f'<div class="error">{st.session_state.error}</div>',
            unsafe_allow_html=True,
        )
    else:
        st.markdown('<div class="error"></div>', unsafe_allow_html=True)

    st.markdown("</section>", unsafe_allow_html=True)

    back_col, next_col = st.columns([1, 1], gap="small")

    with back_col:
        st.markdown('<div class="back-button">', unsafe_allow_html=True)
        if st.button(
            "ATRÁS",
            disabled=(current == 0),
            use_container_width=True,
            key="back_button",
            type="secondary",
        ):
            if current > 0:
                st.session_state.inputs[step["key"]] = st.session_state.get(
                    f"input_{step['key']}"
                )
                st.session_state.current_step -= 1
                st.session_state.error = ""
                st.rerun()
        st.markdown("</div>", unsafe_allow_html=True)

    with next_col:
        st.markdown('<div class="next-button">', unsafe_allow_html=True)
        label = "CALCULAR PESO NETO" if current == len(steps) - 1 else "CONTINUAR"
        if st.button(
            label,
            use_container_width=True,
            key="next_button",
            type="primary",
        ):
            calculate_next()
            st.rerun()
        st.markdown("</div>", unsafe_allow_html=True)

st.markdown(
    '<div class="footer">Aplicación de cálculo de peso neto</div>',
    unsafe_allow_html=True,
)
